# O+D Budgetary Estimate - PDF Export Post-Processor
#
# Opens the xlsx generated by build_estimate.py, applies portrait page setup,
# inserts the logo as a print header (appears on every page), sets footer
# with GC contact line + page numbers, exports to PDF.
#
# Usage: edit the variables in the EDIT THIS BLOCK section, then invoke:
#   powershell -File export_pdf.ps1
#
# Critical: $pdfTmp MUST be outside Dropbox. Excel COM's ExportAsFixedFormat
# fails silently when writing into a synced Dropbox folder. After this script
# completes, move the temp PDF into the project's Bid Documents folder via Bash:
#   mv "/c/Users/<user>/estimate_v<N>.pdf" "<project path>/<filename>.pdf"

# ============================================================
# EDIT THIS BLOCK FOR EACH NEW PROJECT
# ============================================================
$xlsx = "C:\Users\Matt\Matt Nicosia Dropbox\BLDG\BLDG Estimating\260079 - MacDougal Street Restaurant [O+D Builders]\Bid Documents\260079_MacDougal_Budgetary_Estimate_v4.xlsx"
$logo = "C:\Users\Matt\.claude\skills\od-budgetary-estimate\assets\OD_logo.png"
$pdfTmp = "C:\Users\Matt\estimate_v4.pdf"        # MUST be outside Dropbox

$projectTitle = "Estimate: 260079 MacDougal Street Restaurant"
$projectAddress = "69-71 MacDougal St, NY NY 10012"
$footerText = "O+D Builders | 152 West 25th St. Suite 801, New York, NY 10001 | (212) 929-8320"
$dateStr = "05/20/2026"
# ============================================================

if(Test-Path $pdfTmp){ Remove-Item $pdfTmp -Force }

# Kill any zombie Excel processes that might hold the xlsx open
Get-Process -Name "EXCEL" -ErrorAction SilentlyContinue | Stop-Process -Force
Start-Sleep -Milliseconds 500

$excel = New-Object -ComObject Excel.Application
$excel.DisplayAlerts = $false

try {
    $wb = $excel.Workbooks.Open($xlsx)
    $wb.Application.CalculateFull()

    foreach($s in $wb.Worksheets){
        $ps = $s.PageSetup

        # Portrait, Letter, Fit-All-Columns-on-One-Page
        # IMPORTANT: set Zoom = $false BEFORE the FitToPages* properties.
        # FitToPagesTall must be $false (NOT 0) — 0 throws "Unable to set..."
        $ps.Orientation = 1                # xlPortrait
        $ps.PaperSize = 1                  # xlPaperLetter
        $ps.Zoom = $false
        $ps.FitToPagesWide = 1
        $ps.FitToPagesTall = $false

        # Margins — top is wider to accommodate the logo print header
        $ps.LeftMargin = $excel.InchesToPoints(0.7)
        $ps.RightMargin = $excel.InchesToPoints(0.7)
        $ps.TopMargin = $excel.InchesToPoints(1.0)
        $ps.BottomMargin = $excel.InchesToPoints(0.75)
        $ps.HeaderMargin = $excel.InchesToPoints(0.3)
        $ps.FooterMargin = $excel.InchesToPoints(0.3)
        $ps.CenterHorizontally = $true

        # Logo in left print header — "&G" placeholder renders the picture
        $ps.LeftHeaderPicture.Filename = $logo
        $ps.LeftHeaderPicture.Height = 54
        $ps.LeftHeaderPicture.Width = 145
        $ps.LeftHeader = "&G"

        # Right header: project title bold + address italic, two lines
        $ps.RightHeader = "&""Open Sans,Bold""&11 $projectTitle`n&""Open Sans,Italic""&10 $projectAddress"

        # Footer: date left, GC contact center, page number right
        $ps.LeftFooter = "&""Open Sans""&10 $dateStr"
        $ps.CenterFooter = "&""Open Sans""&10 $footerText"
        $ps.RightFooter = "&""Open Sans""&10 Page &P of &N"
    }

    $wb.Save()
    $wb.ExportAsFixedFormat(0, $pdfTmp, 0, $true, $false)

    Start-Sleep -Seconds 3

    if(Test-Path $pdfTmp){
        $size = (Get-Item $pdfTmp).Length
        Write-Output "PDF created: $pdfTmp ($size bytes)"
        Write-Output ""
        Write-Output "Next step (run from Bash):"
        $destName = (Split-Path $xlsx -Leaf).Replace(".xlsx", ".pdf")
        $destFolder = Split-Path $xlsx -Parent
        # Convert Windows path to Bash path
        $bashDest = ($destFolder + "\" + $destName).Replace("C:\", "/c/").Replace("\", "/")
        $bashSrc = $pdfTmp.Replace("C:\", "/c/").Replace("\", "/")
        Write-Output "  mv `"$bashSrc`" `"$bashDest`""
    } else {
        Write-Output "ERROR: PDF was not created. Check that pdfTmp is outside Dropbox."
    }
} catch {
    Write-Output ("ERROR: " + $_.Exception.Message)
} finally {
    if($wb){ $wb.Close($false) }
    if($excel){
        $excel.Quit()
        [System.Runtime.Interopservices.Marshal]::ReleaseComObject($excel) | Out-Null
    }
}
